function renderParent(s,c){const kids=getCollection('alumnos').filter(a=>user.hijos?.includes(a.id));if(s==='inicio'){setHeader('Inicio');c.innerHTML=statCards([['Tutelados',kids.length],['Tareas pendientes',getCollection('tareas').filter(t=>kids.some(k=>k.id===t.alumnoId)&&!t.completada).length],['Materias',getCollection('materias').filter(m=>kids.some(k=>k.grupo===m.grupo)).length],['Avisos',getCollection('avisos').length]])+`<div class="section-head"><h2>Mis hijos / tutelados</h2></div><div class="grid">${kids.map(k=>`<div class="card subject"><strong>${escapeHTML(k.nombre)}</strong><small>Grupo ${escapeHTML(k.grupo)}</small></div>`).join('')}</div>`}else if(s==='tareas'){setHeader('Tareas');c.innerHTML=kids.map(k=>`<div class="section-head"><h2>${escapeHTML(k.nombre)}</h2></div><div class="card">${getCollection('tareas').filter(t=>t.alumnoId===k.id).map(taskRow).join('')||'<div class="empty">Sin tareas.</div>'}</div>`).join('')}else if(s==='calendario'){setHeader('Calendario');c.innerHTML=`<div class="card"><div class="calendar">${Array.from({length:30},(_,i)=>`<div class="day"><b>${i+1}</b><small>${getCollection('eventos').filter(e=>e.fecha==='2026-09-'+String(i+1).padStart(2,'0')).map(e=>escapeHTML(e.titulo)).join('<br>')}</small></div>`).join('')}</div></div>`}else if(s==='materias'){setHeader('Materias');c.innerHTML=`<div class="grid">${getCollection('materias').filter(m=>kids.some(k=>k.grupo===m.grupo)).map(m=>`<div class="card subject"><strong>${escapeHTML(m.nombre)}</strong><small>${escapeHTML(m.docente)}</small><small>${escapeHTML(m.grupo)}</small></div>`).join('')}</div>`}else if(s==='plataformas'){setHeader('Plataformas');c.innerHTML=platformHTML()}else if(s==='avisos'){setHeader('Avisos');c.innerHTML=`<div class="card">${getCollection('avisos').map(a=>`<div class="notice-row"><div><strong>${escapeHTML(a.titulo)}</strong><small class="muted">${escapeHTML(a.texto)}</small></div><small>${a.fecha}</small></div>`).join('')}</div>`}}